// شجرةُ العوامل: المسِ العددَ غيرَ الأوّليِّ واخترْ زوجَ عوامل
export function treeTool(el, start = 36) {
  el.innerHTML = `<div class="row">العدد: ${ansInput('عدد', '110px')}<button class="btn s sm" data-a="new">ابدأ الشجرة</button><button class="btn s sm" data-a="rnd">🎲 عددٌ عشوائيّ</button></div><div class="tree"></div><div class="fb"></div>`;
  let root;
  const mk = n => ({ n, kids: null });
  const leaves = t => t.kids ? [...leaves(t.kids[0]), ...leaves(t.kids[1])] : [t.n];
  const render = () => {
    const H = t => `<div class="tn"><button class="tv ${t.kids ? 'sp' : isPrime(t.n) ? 'pr' : 'cp'}" data-n="${t.id}">${AR(t.n)}</button>${t.kids ? `<div class="tk">${H(t.kids[0])}${H(t.kids[1])}</div>` : ''}</div>`;
    let id = 0; const tag = t => { t.id = id++; if (t.kids) t.kids.forEach(tag); }; tag(root);
    $('.tree', el).innerHTML = H(root);
    const L = leaves(root).sort((a, b) => a - b), done = L.every(isPrime), fb = $('.fb', el);
    fb.innerHTML = done ? `✓ اكتملتِ الشجرة: ${AR(root.n)} = ${pfHTML(root.n)} ${L.length > 1 ? '' : '(عددٌ أوّليّ)'}` : '👆 المسْ عددًا <b style="color:#c0401a">برتقاليًّا</b> (غيرَ أوّليّ) لتحلِّلَه. الأعدادُ <b style="color:#2f8f6a">الخضراءُ</b> أوّليّة.';
    if (done && L.length > 1 && !root.starred) { root.starred = 1; star(1, 'أكملتَ شجرةَ العوامل'); }
    const all = []; const walk = t => { all.push(t); t.kids && t.kids.forEach(walk); }; walk(root);
    $$('.tv.cp', el).forEach(b => b.onclick = () => { const t = all.find(x => x.id === +b.dataset.n); const ps = []; for (let a = 2; a * a <= t.n; a++) if (t.n % a === 0) ps.push([a, t.n / a]);
      fb.innerHTML = `اخترْ عاملينِ حاصلُ ضربِهما ${AR(t.n)}: ` + ps.map(([a, c]) => `<button class="btn s sm" data-p="${a}">${AR(a)} × ${AR(c)}</button>`).join(' ');
      $$('[data-p]', fb).forEach(x => x.onclick = () => { const a = +x.dataset.p; t.kids = [mk(a), mk(t.n / a)]; render(); }); });
  };
  const start2 = n => { if (!(n >= 2 && n <= 10000)) return; root = mk(n); render(); };
  $('[data-a="new"]', el).onclick = () => start2(parseNum($('input', el).value));
  $('[data-a="rnd"]', el).onclick = () => { const n = pick([12, 18, 20, 24, 30, 36, 40, 42, 48, 54, 60, 72, 84, 90, 96, 100, 120, 144]); $('input', el).value = AR(n); start2(n); };
  $('input', el).value = AR(start); start2(start);
}
// طريقةُ القسمةِ المتتالية (السلّم)
function ladderTool(el, n0 = 36) {
  el.innerHTML = `<div class="row">العدد: ${ansInput('عدد', '110px')}<button class="btn s sm">ابدأ</button></div><div class="lad"></div><div class="fb"></div>`;
  const run = n => { let cur = n; const rows = []; const box = $('.lad', el), fb = $('.fb', el);
    const draw = () => { box.innerHTML = `<table class="tb"><tr><th>العدد</th><th>العاملُ الأوّليّ</th></tr>${rows.map(r => `<tr><td>${AR(r[0])}</td><td>${AR(r[1])}</td></tr>`).join('')}<tr><td>${AR(cur)}</td><td>${cur === 1 ? '—' : '؟'}</td></tr></table>`;
      if (cur === 1) { fb.innerHTML = `✓ ظهرَ العددُ ١ فنتوقّف: ${AR(n)} = ${pfHTML(n)}`; return; }
      const opts = shuf([...new Set([...primeFactors(cur).slice(0, 1), ...[2, 3, 5, 7].filter(p => p !== primeFactors(cur)[0]).slice(0, 2)])]);
      fb.innerHTML = `على أيِّ عددٍ أوّليٍّ يقبلُ ${AR(cur)} القسمة؟ ` + opts.map(p => `<button class="btn s sm" data-p="${p}">${AR(p)}</button>`).join(' ');
      $$('[data-p]', fb).forEach(b => b.onclick = () => { const p = +b.dataset.p; if (cur % p) { b.classList.add('no'); b.textContent = '✗'; return; } rows.push([cur, p]); cur /= p; draw(); }); };
    draw(); };
  $('button', el).onclick = () => { const v = parseNum($('input', el).value); if (v >= 2) run(v); }; $('input', el).value = AR(n0); run(n0);
}

