export const subst = (e, V) => { let s = e.replace(/ـ/g, ''); s = s.replace(/([\dء-ي])\s*(?=[ء-ي])/g, '$1 × '); return s.replace(/[ء-ي]/g, c => c in V ? String(V[c]) : c); };
