const eqQ = (tag, eq, letter, x, o = {}) => num(tag, o.text || `حُلَّ المعادلةَ ذهنيًّا: ${eqText(eq)}`, x, { title: eqText(eq), sol: eqSol(eq, letter, x), hints: ['فكّرْ: ما العددُ الذي يجعلُ الطرفينِ متساويين؟', 'جرّبْ قيمةً، ثم عوّضْ وتحقّقْ.'], skill: 'eqm', ...o });
const eqC = (tag, eq, letter, vals, x, o = {}) => ch(tag, `حدّدْ حلَّ المعادلة ${eqText(eq)} من القيم: ${vals.map(AR).join('، ')}`, vals.map(AR), vals.indexOf(x), { title: eqText(eq), sol: eqSol(eq, letter, x), hints: ['عوّضْ بكلِّ قيمةٍ وتحقّقْ هل الطرفانِ متساويان.'], skill: 'eqc', ...o });
const ftQ = (tag, rule, ins, o = {}) => fld(tag, o.text || `أكملْ جدولَ الدالّة: المدخلةُ (س)، والمخرجةُ (${R(rule)})`, ins.map(x => [`س = ${AR(x)} ←`, evalExpr(subst(rule, { س: x }))]), { title: 'أكملِ الجدول: ' + R(rule), html: tbl([['المدخلة (س)', ...ins.map(AR)], ['المخرجة (' + R(rule) + ')', ...ins.map(() => '■')]]), sol: ins.map(x => `${R(subst(rule, { س: x }))} = ${AR(evalExpr(subst(rule, { س: x })))}`), hints: ['عوّضْ بقيمةِ س في قاعدةِ الدالّة.'], skill: 'ftable', ...o });
const frQ = (tag, rule, ins, o = {}) => exq(tag, o.text || 'أوجدْ قاعدةَ الدالّةِ الممثّلةِ بالجدول:', rule, { html: tbl([['س', ...ins.map(AR)], ['■', ...ins.map(x => AR(evalExpr(subst(rule, { س: x }))))]]), title: 'أوجدِ القاعدة', kp: 'expr', sol: ['القاعدة: ' + R(rule), ...ins.map(x => `${R(subst(rule, { س: x }))} = ${AR(evalExpr(subst(rule, { س: x })))} ✓`)], hints: ['قارنْ كلَّ مخرجةٍ بمدخلتِها: هل تزيدُ بمقدارٍ ثابت؟ أم هي أمثالُها؟', 'جرّبْ قاعدتَك على أكثرَ من مدخلة.'], skill: 'frule', ...o });

/* ── أداة: آلةُ التعويض ── */
function substTool(el, list) {
  list = list || [['16 + ب', { ب: 25 }], ['س - ص', { س: 64, ص: 27 }], ['5ن + 4', { ن: 3 }], ['(ق + 3) × ق ÷ 2', { ق: 8 }], ['7 + 3ت', { ت: 5 }]];
  el.innerHTML = `<div class="row"><select class="sq">${list.map((x, i) => `<option value="${i}">${x[0].replace(/\d+/g, d => AR(d))}</option>`).join('')}</select></div><div class="sls"></div><div class="sbox"></div>`;
  let V;
  const draw = () => { const e = list[+$('.sq', el).value][0], s = subst(e, V); $('.sbox', el).innerHTML = `<div class="big">${R(e)}</div><div class="meta">عوّضْ بالقيم:</div><ol class="calc">${steps(s).map(x => `<li>${x}</li>`).join('')}</ol><div class="fb">القيمة = <b>${fmt(evalExpr(s))}</b></div>`; };
  const load = () => { const [e, V0] = list[+$('.sq', el).value]; V = { ...V0 }; $('.sls', el).innerHTML = Object.keys(V).map(k => `<div class="sl">${k} = <input type="range" min="0" max="${Math.max(20, V[k] * 2)}" value="${V[k]}" data-k="${k}"><b>${AR(V[k])}</b></div>`).join(''); $$('.sls input', el).forEach(r => r.oninput = () => { V[r.dataset.k] = +r.value; r.nextElementSibling.textContent = AR(r.value); draw(); }); draw(); };
  $('.sq', el).onchange = load; load();
}
/* ── أداة: آلةُ الدالّة ── */
